// Map con objetos como claves — caso real: metadata de elementos DOM
// (Simulamos sin DOM usando objetos como 'elementos')
const metadata = new Map();

const btn1 = { id: 'btn-submit', tipo: 'button' };
const btn2 = { id: 'btn-cancel', tipo: 'button' };
const input = { id: 'input-email', tipo: 'input' };

metadata.set(btn1, { clicks: 0, ultimoClick: null });
metadata.set(btn2, { clicks: 0, ultimoClick: null });
metadata.set(input, { cambios: 0, valorActual: '' });

// Simula clicks
const datosBtn1 = metadata.get(btn1);
datosBtn1.clicks++;
datosBtn1.ultimoClick = Date.now();

console.log('Clicks en btn1:', metadata.get(btn1).clicks); // 1
console.log('Clicks en btn2:', metadata.get(btn2).clicks); // 0
console.log('Total elementos rastreados:', metadata.size);  // 3

// Agrupar elementos con Map (como un groupBy)
function agrupar(array, obtenerClave) {
  const grupos = new Map();
  for (const item of array) {
    const clave = obtenerClave(item);
    if (!grupos.has(clave)) grupos.set(clave, []);
    grupos.get(clave).push(item);
  }
  return grupos;
}

const productos = [
  { nombre: 'Manzana', categoria: 'frutas', precio: 1200 },
  { nombre: 'Pera', categoria: 'frutas', precio: 1500 },
  { nombre: 'Zanahoria', categoria: 'verduras', precio: 800 },
  { nombre: 'Brócoli', categoria: 'verduras', precio: 1000 },
  { nombre: 'Naranja', categoria: 'frutas', precio: 1300 },
];

const porCategoria = agrupar(productos, p => p.categoria);

console.log('Frutas:', porCategoria.get('frutas').map(p => p.nombre));
console.log('Verduras:', porCategoria.get('verduras').map(p => p.nombre));
console.log('Categorías:', [...porCategoria.keys()]);

