function contarPalabras(texto) {
  const frecuencias = new Map();
  const palabras = texto.toLowerCase().split(' ');

  for (const palabra of palabras) {
    if (frecuencias.has(palabra)) {
      frecuencias.set(palabra, frecuencias.get(palabra) + 1);
    } else {
      frecuencias.set(palabra, 1);
    }
  }

  return frecuencias;
}

const frecuencias = contarPalabras('el gato y el perro y el gato');
const veces_el = frecuencias.get('el');
const veces_gato = frecuencias.get('gato');
const veces_y = frecuencias.get('y');
const totalPalabrasUnicas = frecuencias.size;

console.log('el:', veces_el, '| gato:', veces_gato, '| y:', veces_y);
console.log('Palabras únicas:', totalPalabrasUnicas);

class CacheLimitado {
  #mapa;
  #capacidad;

  constructor(capacidad) {
    this.#capacidad = capacidad;
    this.#mapa = new Map();
  }

  get(clave) {
    return this.#mapa.get(clave);
  }

  set(clave, valor) {
    if (this.#mapa.has(clave)) {
      this.#mapa.delete(clave); // Eliminar y re-insertar actualiza el orden
    }
    this.#mapa.set(clave, valor);

    if (this.#mapa.size > this.#capacidad) {
      // Elimina el primero (más antiguo)
      const masAntiguo = this.#mapa.keys().next().value;
      this.#mapa.delete(masAntiguo);
    }
  }

  get size() {
    return this.#mapa.size;
  }
}

const cache = new CacheLimitado(3);
cache.set('a', 1);
cache.set('b', 2);
cache.set('c', 3);

const tamano1 = cache.size; // 3
cache.set('d', 4); // Supera capacidad → elimina 'a'

const tieneA = cache.get('a') !== undefined; // false — fue eliminado
const tieneD = cache.get('d') !== undefined; // true
const tamano2 = cache.size;                  // 3

console.log('Tamaño:', tamano1, tamano2);
console.log('Tiene a:', tieneA, '| Tiene d:', tieneD);
